"use client";

import { useState, useEffect } from 'react';
import { FaProjectDiagram, FaClipboardList, FaCheckCircle, FaTachometerAlt, FaSignOutAlt, FaBars } from 'react-icons/fa';
import Link from 'next/link';
import Image from 'next/image';
import cookies from 'js-cookie';
import { jwtDecode } from 'jwt-decode';

const Sidebar = () => {
  const [isAffectationOpen, setAffectationOpen] = useState(false);
  const [isCreationCompteOpen, setCreationCompteOpen] = useState(false);
  const [isIMPORTATIONOpen, setIMPORTATIONOpen] = useState(false);
  const [isGenererOpen, setGenererOpen] = useState(false);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [userRole, setUserRole] = useState('');
  const [userId, setUserId] = useState('');

  useEffect(() => {
    // Récupérer les informations de l'utilisateur depuis le cookie JWT
    const getUserInfo = () => {
      const token = cookies.get('token');
      if (token) {
        try {
          const decoded = jwtDecode(token);
          console.log("Token décodé:", decoded); // Pour déboguer
          setUserRole(decoded.role);
          
          // Privilégier user_id dans tous les cas
          if (decoded.user_id) {
            setUserId(decoded.user_id);
            console.log("UserID set from user_id:", decoded.user_id);
          } else if (decoded.userId) {
            setUserId(decoded.userId);
            console.log("UserID set from userId:", decoded.userId);
          }
        } catch (error) {
          console.error('Erreur lors du décodage du token:', error);
        }
      }
    };
  
    getUserInfo();
  }, []); // Dépendances vides pour n'exécuter qu'une seule fois
  
  const toggleAffectation = () => setAffectationOpen(!isAffectationOpen);
  const toggleCreationCompte = () => setCreationCompteOpen(!isCreationCompteOpen);
  const toggleIMPORTATION = () => setIMPORTATIONOpen(!isIMPORTATIONOpen);
  const toggleGenerer = () => setGenererOpen(!isGenererOpen);
  const toggleSidebar = () => setSidebarOpen(!isSidebarOpen);

  // Vérifier si l'utilisateur est un responsable de filière
  const isCoordinationAllowed = userRole === 'responsableFiliere';
  
  return (
    <div className={`h-screen ${isSidebarOpen ? 'w-64' : 'w-16'} bg-[#2C3E50] text-white p-4 transition-all duration-500 shadow-lg flex flex-col`}>
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center">
          <Image
            src="/ESTSLOGO24.png"
            alt="School Logo"
            width={200}
            height={200}
            style={{ marginTop: '-50px' }}
          />
        </div>

        <button
          className="md:hidden text-2xl focus:outline-none"
          onClick={toggleSidebar}
          aria-label="Toggle Sidebar"
        >
          <FaBars />
        </button>
      </div>

      <ul className="space-y-2">
        <Link href="/dashboard">
          <li className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
            <FaTachometerAlt /> {isSidebarOpen && 'Dashboard'}
          </li>
        </Link>

        {/* Afficher la section Coordination uniquement pour les responsables de filière */}
        {isCoordinationAllowed && (
          <>
            <li
              className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
              onClick={toggleAffectation}
            >
              <FaClipboardList /> {isSidebarOpen && 'Coordination'}
            </li>

            {isAffectationOpen && (
              <ul className="ml-5 space-y-2">
                <li
                  className={`p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
                  onClick={toggleIMPORTATION}
                >
                  {isSidebarOpen && 'Répartition'}
                </li>

                {isIMPORTATIONOpen && (
                  <ul className="ml-5 space-y-2">
                    <Link href="/users/readEtu">
                      <li className="flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300">
                        <FaProjectDiagram /> {isSidebarOpen && 'Gestion Étudiants'}
                      </li>
                    </Link>
                    <Link href="/users/readEnca">
                      <li className="flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300">
                        <FaProjectDiagram /> {isSidebarOpen && 'Gestion Encadrants'}
                      </li>
                    </Link>
                    <Link href="/users/readTute">
                      <li className="flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300">
                        <FaProjectDiagram /> {isSidebarOpen && 'Gestion Tuteur'}
                      </li>
                    </Link>
                    <Link href="/users/readSuj">
                      <li className="flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300">
                        <FaProjectDiagram /> {isSidebarOpen && 'Gestion Sujet'}
                      </li>
                    </Link>
                    <Link href="/users/readgenerer">
                      <li className="flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300">
                        <FaProjectDiagram /> {isSidebarOpen && 'Gestion des groupes'}
                      </li>
                    </Link>
                  </ul>
                )}

                <li
                  className={`p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
                  onClick={toggleGenerer}
                >
                  {isSidebarOpen && 'Affectation'}
                </li>

                {isGenererOpen && (
                  <ul className="ml-5 space-y-2">
                    <Link href="/users/readaffec">
                      <li className="flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300">
                        <FaProjectDiagram /> {isSidebarOpen && 'Attribution'}
                      </li>
                    </Link>
                  </ul>
                )}

                <li
                  className={`p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
                  onClick={toggleCreationCompte}
                >
                  {isSidebarOpen && 'Création des Comptes'}
                </li>

                {isCreationCompteOpen && (
                  <ul className="ml-5 space-y-2">
                    <Link href="/users/compte">
                      <li className="flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300">
                        <FaProjectDiagram /> {isSidebarOpen && 'Créer Compte'}
                      </li>
                    </Link>
                  </ul>
                )}
              </ul>
            )}
          </>
        )}

        {/* Afficher la consultation en fonction du rôle de l'utilisateur */}
        {userRole === 'tuteur' && userId &&(
          <Link href={`/users/Tutinterface/${userId}`}>
            <li className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
              <FaCheckCircle /> {isSidebarOpen && 'Consultation'}
            </li>
          </Link>
        )}

        {userRole === 'encadrant' && userId && (
          <Link href={`/users/EncadrantInterface/${userId}`}>
            <li className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
              <FaCheckCircle /> {isSidebarOpen && 'Consultation'}
            </li>
          </Link>
        )}

        {userRole === 'etudiant' && userId &&(
          <Link href={`/users/Etinterface/${userId}`}>
            <li className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
              <FaCheckCircle /> {isSidebarOpen && 'Consultation'}
            </li>
          </Link>
        )}

        {/* Ces sections sont visibles pour tous les utilisateurs */}
        <li className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
          <FaCheckCircle /> {isSidebarOpen && 'Suivi'}
        </li>
        <li className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
          <FaCheckCircle /> {isSidebarOpen && 'Soutenance'}
        </li>

        <Link href={`/`}>
          <li className={`flex items-center gap-3 p-3 hover:bg-[#34495E] cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
            <FaSignOutAlt /> {isSidebarOpen && 'Déconnexion'}
          </li>
        </Link>
      </ul>
    </div>
  );


  
};

export default Sidebar;